insert into public.collectible_species ("id","kind","name","description","swim_y_min","swim_y_max","speed","size","rarity","thumbnail_path","sell_price","sprite_sheet_path","native_region_id","movement_type","flip_with_direction","travel_direction") values
('bluegrove-bluecheek-filefish','fish','푸른볼 쥐치','동그란 볼에 푸른 물방울 무늬가 있는 쥐치. 작은 입을 오므리며 푸른골의 해초 사이를 헤엄친다.','0.18','0.82','0.028',62,'common','fish/normal/bluegrove-bluecheek-filefish_thumbnail.png',65,'fish/normal/bluegrove-bluecheek-filefish_sprite.png','bluegrove','swim',true,'both'),
('bluegrove-changryu-thousand-currents','fish','천 개의 물살, 창류','천 갈래 물살을 지느러미에 두른 푸른 해룡. 창류가 꼬리를 휘두르면 은빛 물고기 떼가 둥근 물길을 그린다.','0.18','0.82','0.018',155,'mythic','fish/mythic/bluegrove-changryu-thousand-currents_thumbnail.png',3200,'fish/mythic/bluegrove-changryu-thousand-currents_sprite.png','bluegrove','swim',true,'both'),
('bluegrove-lost-ship-nameplate','trash','돌아오지 못한 배의 명패','돌아오지 못한 배의 이름을 품은 황동 명패. 따개비와 푸른 해초 사이로 오래된 글자의 흔적이 남아 있다.','0.65','0.82','0.012',50,'common','trash/normal/bluegrove-lost-ship-nameplate_thumbnail.png',22,null,'bluegrove','swim',false,'both'),
('bluegrove-sandsleep-flounder','fish','모래잠 넙치','모래빛 몸에 청록색 점이 흩어진 넙치. 물결 같은 지느러미를 펼치고 푸른골 바닥에서 느긋하게 쉰다.','0.18','0.82','0.028',68,'common','fish/normal/bluegrove-sandsleep-flounder_thumbnail.png',68,'fish/normal/bluegrove-sandsleep-flounder_sprite.png','bluegrove','swim',true,'both'),
('bluegrove-waveworn-driftwood','trash','물결 깎은 유목','푸른골의 물결이 오랜 시간 매만진 유목. 매끈한 나뭇결에 작은 조개와 해초가 걸려 있다.','0.65','0.82','0.012',60,'common','trash/normal/bluegrove-waveworn-driftwood_thumbnail.png',20,null,'bluegrove','swim',false,'both'),
('lunea-dreamkeeper','fish','루네아의 꿈지기','이마의 달빛 보석과 별무늬 지느러미를 가진 은백색 가오리. 긴 날개를 펼쳐 잠든 루네아의 꿈을 감싸 준다.','0.18','0.82','0.022',112,'epic','fish/epic/lunea-dreamkeeper_thumbnail.png',1200,'fish/epic/lunea-dreamkeeper_sprite.png','mistmoon','swim',true,'both'),
('lunea-mirrorscale','fish','루네아의 거울비늘','넓은 은빛 비늘에 달빛을 비추는 우아한 물고기. 루네아가 가까이 오면 온몸에 초승달의 잔상이 흐른다.','0.18','0.82','0.022',110,'epic','fish/epic/lunea-mirrorscale_thumbnail.png',1280,'fish/epic/lunea-mirrorscale_sprite.png','mistmoon','swim',true,'both'),
('mistmoon-mistwhisker-loach','fish','안개수염 미꾸리','우윳빛 몸과 연보라 수염을 가진 통통한 미꾸리. 루네아가 쉬어 간 물길에서 수염을 살랑인다.','0.18','0.82','0.028',60,'common','fish/normal/mistmoon-mistwhisker-loach_thumbnail.png',66,'fish/normal/mistmoon-mistwhisker-loach_sprite.png','mistmoon','swim',true,'both'),
('mistmoon-moonletter-butterflyfish','fish','달편지 나비고기','접힌 편지 같은 지느러미와 초승달 봉인 무늬가 있는 나비고기. 루네아에게 전하지 못한 소원을 옮긴다.','0.18','0.82','0.028',68,'rare','fish/rare/mistmoon-moonletter-butterflyfish_thumbnail.png',350,'fish/rare/mistmoon-moonletter-butterflyfish_sprite.png','mistmoon','swim',true,'both'),
('mistmoon-moonpillow-flounder','fish','달베개 가자미','작은 베개처럼 통통하고 납작한 연보라 가자미. 루네아가 잠들면 곁의 모래에 파고들어 함께 눈을 감는다.','0.18','0.82','0.028',64,'common','fish/normal/mistmoon-moonpillow-flounder_thumbnail.png',68,'fish/normal/mistmoon-moonpillow-flounder_sprite.png','mistmoon','swim',true,'both'),
('mistmoon-moonspot-salamander','fish','달점 도롱뇽','남보라색 등에 작은 달무늬가 떠 있는 도롱뇽. 루네아의 달빛을 등에 모으고 조용한 물밑을 산책한다.','0.18','0.82','0.028',65,'common','fish/normal/mistmoon-moonspot-salamander_thumbnail.png',70,'fish/normal/mistmoon-moonspot-salamander_sprite.png','mistmoon','swim',true,'both'),
('mistmoon-postman-hermit','fish','안개 우체부 소라게','초승달 자물쇠가 달린 우편함을 메고 다니는 소라게. 안개마을의 작은 편지를 루네아의 물길로 배달한다.','0.18','0.82','0.028',62,'common','fish/normal/mistmoon-postman-hermit_thumbnail.png',72,'fish/normal/mistmoon-postman-hermit_sprite.png','mistmoon','swim',true,'both'),
('mistmoon-sleeptalk-jellyfish','fish','잠꼬대 방울해파리','수면모자 같은 갓을 쓴 작은 해파리. 루네아의 자장가를 들으며 촉수를 오므릴 때마다 희미한 달빛이 번진다.','0.18','0.82','0.028',58,'common','fish/normal/mistmoon-sleeptalk-jellyfish_thumbnail.png',67,'fish/normal/mistmoon-sleeptalk-jellyfish_sprite.png','mistmoon','swim',true,'both'),
('mistmoon-yumyeon-moonrest','fish','달을 베고 잠든, 유면','은빛 달 갑옷과 긴 보라색 지느러미를 두른 물범 기사. 초승달을 베개 삼아 졸면서도 루네아 곁을 지킨다.','0.18','0.82','0.022',108,'epic','fish/epic/mistmoon-yumyeon-moonrest_thumbnail.png',1250,'fish/epic/mistmoon-yumyeon-moonrest_sprite.png','mistmoon','swim',true,'both'),
('shared-cheolgak-sunken-harbor','fish','가라앉은 항구의 주인, 철각','가라앉은 배의 갑옷과 닻 모양 집게를 가진 거대한 바닷가재. 잊힌 항구들의 기억을 싣고 모든 바다를 순회한다.','0.18','0.82','0.018',150,'mythic','fish/mythic/shared-cheolgak-sunken-harbor_thumbnail.png',3300,'fish/mythic/shared-cheolgak-sunken-harbor_sprite.png',null,'swim',true,'both'),
('shared-maru-returning-wave','fish','돌아오는 파도, 마루','등 위에 작은 파도가 끊임없이 밀려오는 진주빛 물범. 어느 바다에 놓아주어도 언젠가 다시 만난다고 한다.','0.18','0.82','0.018',135,'mythic','fish/mythic/shared-maru-returning-wave_thumbnail.png',2950,'fish/mythic/shared-maru-returning-wave_sprite.png',null,'swim',true,'both'),
('shared-yurion-bottled-sea','fish','병 속의 바다, 유리온','투명한 몸 안에 작은 섬과 바다를 품은 고래상어. 어느 해역에서 만나도 유리온의 몸속에는 따뜻한 파도가 친다.','0.18','0.82','0.018',148,'mythic','fish/mythic/shared-yurion-bottled-sea_thumbnail.png',3100,'fish/mythic/shared-yurion-bottled-sea_sprite.png',null,'swim',true,'both')
